const output = [];
const now = Date.now();

function decode(value) {
  return String(value || '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&#39;/gi, "'")
    .replace(/&quot;/gi, '"')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function field(html, label) {
  const escaped = String(label).replace(/[.*+?^$(){}|[\]\\]/g, '\\$&');
  const pattern = new RegExp('<strong>\\s*' + escaped + '\\s*<\\/strong>[\\s\\S]*?<pre[^>]*>([\\s\\S]*?)<\\/pre>', 'i');
  return decode(pattern.exec(html)?.[1] || '');
}

function normalizeEmail(value) {
  const candidate = String(value || '').trim().toLowerCase();
  return /^[a-z0-9.!#$%&'*+/=?^_{|}~-]+@[a-z0-9.-]+\.[a-z]{2,}$/i.test(candidate) ? candidate : '';
}

for (const item of $input.all()) {
  const email = item.json || {};
  const html = String(email.body?.content || '');
  const subject = String(email.subject || '').trim();
  const sourceFromEmail = String(email.from?.emailAddress?.address || '').trim().toLowerCase();
  const toAddresses = (email.toRecipients || []).map(x => String(x?.emailAddress?.address || '').toLowerCase());
  const customerEmail = normalizeEmail(field(html, 'E-Mail'));
  const customerName = field(html, 'Name').slice(0, 160);
  const firstName = customerName.split(/\s+/).filter(Boolean)[0] || '';
  const company = field(html, 'Unternehmen').slice(0, 200);
  const projectDescription = field(html, 'Projektbeschreibung').slice(0, 2000);
  const objectType = field(html, 'Objekttyp').slice(0, 120);
  const consent = field(html, 'Datenschutz_bestaetigt');
  const gclid = field(html, 'gclid').slice(0, 200);
  const isTarget = sourceFromEmail === 'submissions@formsubmit.co'
    && /^Neue\s+Google-Ads-Anfrage\s*[–-]\s*RIESENOBJEKTE$/i.test(subject)
    && toAddresses.includes('info@riesenobjekte.de')
    && /https:\/\/www\.riesenobjekte\.de\//i.test(html)
    && /Google Ads Landingpage/i.test(html);
  const isQa = /(?:^|\b)(?:qa|test)(?:\b|[-_])/i.test([customerName, projectDescription, gclid].join(' '))
    || /nicht bearbeiten/i.test([customerName, projectDescription].join(' '))
    || /^TEST-/i.test(gclid);
  const validCustomer = Boolean(customerEmail)
    && customerEmail !== sourceFromEmail
    && !customerEmail.endsWith('@formsubmit.co');
  const consentOk = /^ja$/i.test(consent);
  const shouldSend = isTarget && !isQa && validCustomer && consentOk;
  const reasons = [];
  if (!isTarget) reasons.push('not_riesenobjekte_formsubmit');
  if (isQa) reasons.push('qa_test');
  if (!validCustomer) reasons.push('invalid_customer_email');
  if (!consentOk) reasons.push('missing_consent');
  const messageId = String(email.id || '').trim();
  const internetMessageId = String(email.internetMessageId || '').trim();
  const conversationId = String(email.conversationId || messageId).trim();
  const idempotencyKey = 'riesenobjekte-form-autoreply:' + (internetMessageId || messageId);

  output.push({json:{
    shouldSend,
    skipReason: reasons.join(','),
    messageId,
    internetMessageId,
    conversationId,
    idempotencyKey,
    sourceFromEmail,
    customerEmail,
    customerName,
    firstName,
    company,
    projectDescription,
    objectType,
    consent,
    gclid,
    subject,
    receivedAt: String(email.receivedDateTime || ''),
    _startTime: now
  }});
}
return output;

let base = {};
try { base = $('Normalize & Validate Lead').first().json; } catch (_) {}
let sent = {};
try { sent = $('Send RIESENOBJEKTE AutoReply').first().json || {}; } catch (_) {}
const incoming = $input.first().json || {};
const message = String(incoming.error?.message || incoming.message || incoming.description || 'Unknown workflow error')
  .replace(/[\u0000-\u001F]+/g, ' ')
  .slice(0, 1500);
const sentMessageId = String(sent.messageId || '').trim();
const sendAccepted = sentMessageId !== '' && Array.isArray(sent.accepted) && sent.accepted.length > 0;
return [{json:{
  request_id: base.idempotencyKey || '',
  message_id: base.messageId || '',
  internet_message_id: base.internetMessageId || '',
  conversation_id: base.conversationId || '',
  from_email: base.customerEmail || '',
  from_name: base.customerName || '',
  subject: base.subject || '',
  message_source: 'riesenobjekte_formsubmit',
  category: 'general',
  draft_created: sendAccepted,
  draft_id: sendAccepted ? sentMessageId : '',
  draft_body_preview: sendAccepted ? 'RIESENOBJEKTE Eingangsbestätigung per SMTP versendet; Protokollierung fehlgeschlagen' : '',
  error_message: message,
  retryable: sendAccepted ? false : /timeout|temporar|rate limit|429|5\d\d|socket|connection|econn/i.test(message),
  processing_time_ms: Math.max(0, Date.now() - Number(base._startTime || Date.now()))
}}];

const record = $('Build Failure Record').first().json;
throw new Error('RIESENOBJEKTE FormSubmit AutoReply failed: ' + String(record.error_message || 'unknown error'));
return [];
